"""NEURON simulation comparing standard vs modified K+ channel expressionCompares a standard neuron with one having:- KV12.3 (KCNH8/Elk3) upregulated - EAG family, voltage-gated K+ channel- KV4.3 (KCND3) downregulated - Shal family, A-type K+ channel"""from neuron import h, guifrom neuron.units import ms, mVimport matplotlib.pyplot as pltimport numpy as np# Load standard mechanismsh.load_file('stdrun.hoc')class NeuronModel:    """Simple neuron model with configurable K+ channels"""        def __init__(self, name="neuron"):        self.name = name                # Create a simple soma        self.soma = h.Section(name=f'soma_{name}')        self.soma.L = 20  # microns        self.soma.diam = 20  # microns        self.soma.nseg = 1                # Insert basic mechanisms        self.soma.insert('hh')  # Hodgkin-Huxley channels                # Store recordings        self.v_vec = h.Vector()        self.t_vec = h.Vector()        self.i_vec = h.Vector()                # Setup recording        self.v_vec.record(self.soma(0.5)._ref_v)        self.t_vec.record(h._ref_t)                # Create current clamp for stimulation        self.stim = h.IClamp(self.soma(0.5))            def set_standard_channels(self):        """Set standard K+ channel conductances"""        # Standard HH K+ conductance        self.soma.gkbar_hh = 0.036  # S/cm2 (standard value)            def set_modified_channels(self, kv12_factor=2.0, kv4_factor=0.3):        """        Modify K+ channels to simulate:        - KV12.3 (KCNH8/Elk3) upregulation - EAG family delayed rectifier        - KV4.3 (KCND3) downregulation - Shal family A-type K+ current                Note: In standard HH model, gkbar represents delayed rectifier K+ channels        This is a simplified approximation. For accurate KV12.3 modeling, you need        specific KCNH8 channel mechanisms (see advanced script).                KV12.3 has distinct properties from Kv1.x channels:        - Slower activation kinetics        - Different voltage dependence        - Part of EAG family (not Shaker family like Kv1.2)                Parameters:        -----------        kv12_factor : float            Multiplier for delayed rectifier K+ conductance (>1 = upregulation)            This approximates KV12.3 upregulation using HH K+ channels        kv4_factor : float            Multiplier for A-type K+ conductance (<1 = downregulation)        """        # Increase delayed rectifier as proxy for KV12.3 upregulation        # Note: This is simplified - real KV12.3 has different kinetics        self.soma.gkbar_hh = 0.036 * kv12_factor                # Note: Standard HH doesn't have A-type current        # For proper A-type modeling, you'd need to insert 'kap' or 'kad' mechanisms        # or custom Kv4.3 mechanisms if available            def stimulate(self, delay=5, duration=20, amplitude=0.3):        """Setup current injection stimulus"""        self.stim.delay = delay  # ms        self.stim.dur = duration  # ms        self.stim.amp = amplitude  # nA            def run_simulation(self, tstop=50):        """Run the simulation"""        h.finitialize(-65 * mV)        h.continuerun(tstop * ms)                return np.array(self.t_vec), np.array(self.v_vec)def compare_neurons():    """Compare standard vs modified K+ channel expression"""        print("Setting up neuron models...")        # Create two neuron models    neuron_standard = NeuronModel("standard")    neuron_modified = NeuronModel("modified")        # Configure channels    neuron_standard.set_standard_channels()    neuron_modified.set_modified_channels(kv12_factor=2.0, kv4_factor=0.3)        # Setup identical stimulation    stim_amp = 0.3  # nA    neuron_standard.stimulate(delay=5, duration=20, amplitude=stim_amp)    neuron_modified.stimulate(delay=5, duration=20, amplitude=stim_amp)        print(f"Running simulations with {stim_amp} nA stimulus...")        # Run simulations    t_std, v_std = neuron_standard.run_simulation(tstop=50)    t_mod, v_mod = neuron_modified.run_simulation(tstop=50)        # Analyze firing patterns    def count_spikes(v, threshold=-20):        """Count action potentials"""        crossings = np.where(np.diff(np.signbit(v - threshold)))[0]        spikes = crossings[::2]  # Take every other crossing (upward)        return len(spikes), spikes        n_spikes_std, spikes_std = count_spikes(v_std)    n_spikes_mod, spikes_mod = count_spikes(v_mod)        print(f"\nResults:")    print(f"Standard neuron: {n_spikes_std} spikes")    print(f"Modified neuron (KV12.3↑, KV4.3↓): {n_spikes_mod} spikes")        # Plot comparison    fig, axes = plt.subplots(2, 1, figsize=(12, 8), sharex=True)        # Voltage traces    axes[0].plot(t_std, v_std, 'b-', linewidth=2, label='Standard')    axes[0].plot(t_mod, v_mod, 'r-', linewidth=2, label='KV12.3↑, KV4.3↓')    axes[0].set_ylabel('Membrane Potential (mV)', fontsize=12)    axes[0].set_title('Neuron Firing Comparison', fontsize=14, fontweight='bold')    axes[0].legend(fontsize=11)    axes[0].grid(True, alpha=0.3)    axes[0].axhline(y=-20, color='gray', linestyle='--', alpha=0.5, label='Spike threshold')        # Highlight stimulus period    axes[0].axvspan(5, 25, alpha=0.1, color='green', label='Stimulus')        # Difference plot    axes[1].plot(t_std, v_mod - v_std, 'purple', linewidth=2)    axes[1].set_xlabel('Time (ms)', fontsize=12)    axes[1].set_ylabel('Voltage Difference (mV)', fontsize=12)    axes[1].set_title('Modified - Standard', fontsize=12)    axes[1].grid(True, alpha=0.3)    axes[1].axhline(y=0, color='black', linestyle='-', linewidth=0.5)    axes[1].axvspan(5, 25, alpha=0.1, color='green')        plt.tight_layout()    #plt.savefig('/mnt/user-data/outputs/kv_channel_comparison.png', dpi=300, bbox_inches='tight')    print(f"\nPlot saved to kv_channel_comparison.png")        # Additional analysis plot    fig2, axes2 = plt.subplots(1, 2, figsize=(14, 5))        # Overlay of first spike    spike_window = 30  # ms around first spike    if len(spikes_std) > 0 and len(spikes_mod) > 0:        t_spike_std = t_std[spikes_std[0]]        idx_std = np.where((t_std >= t_spike_std - 5) & (t_std <= t_spike_std + spike_window))[0]        idx_mod = np.where((t_mod >= t_spike_std - 5) & (t_mod <= t_spike_std + spike_window))[0]                axes2[0].plot(t_std[idx_std] - t_spike_std, v_std[idx_std], 'b-', linewidth=2, label='Standard')        axes2[0].plot(t_mod[idx_mod] - t_spike_std, v_mod[idx_mod], 'r-', linewidth=2, label='Modified')        axes2[0].set_xlabel('Time from spike onset (ms)', fontsize=11)        axes2[0].set_ylabel('Membrane Potential (mV)', fontsize=11)        axes2[0].set_title('First Action Potential Comparison', fontsize=12, fontweight='bold')        axes2[0].legend()        axes2[0].grid(True, alpha=0.3)        # Phase plane (dV/dt vs V)    dv_std = np.gradient(v_std, t_std)    dv_mod = np.gradient(v_mod, t_mod)        axes2[1].plot(v_std, dv_std, 'b-', alpha=0.7, linewidth=1.5, label='Standard')    axes2[1].plot(v_mod, dv_mod, 'r-', alpha=0.7, linewidth=1.5, label='Modified')    axes2[1].set_xlabel('Membrane Potential (mV)', fontsize=11)    axes2[1].set_ylabel('dV/dt (mV/ms)', fontsize=11)    axes2[1].set_title('Phase Plane', fontsize=12, fontweight='bold')    axes2[1].legend()    axes2[1].grid(True, alpha=0.3)        plt.tight_layout()   # plt.savefig('/mnt/user-data/outputs/kv_channel_detailed_analysis.png', dpi=300, bbox_inches='tight')    print(f"Detailed analysis plot saved to kv_channel_detailed_analysis.png")        return neuron_standard, neuron_modifiedif __name__ == '__main__':    print("=" * 60)    print("K+ Channel Modulation Effects on Neuron Firing")    print("=" * 60)        # Run comparison    std, mod = compare_neurons()        print("\n" + "=" * 60)    print("Simulation complete!")    print("=" * 60)    print("\nNote: This uses simplified HH model channels.")    print("For accurate KV12.3 (KCNH8/Elk3) and KV4.3 (KCND3) modeling,")    print("use specific channel mechanisms from ModelDB or create custom")    print("MOD files. KV12.3 is an EAG-family channel, NOT Kv1.2!")